const promotableSymbol: u16 = 96;

/// The keyword terminals of `@keywords ctx`; a value becomes its leaf's id.
pub const CtxId = enum(u16) {
    UNIQUE = 1,
    FROM,
    STATIC,
};

/// The `ctx` keyword `text` spells, or null.
pub fn ctxAs(text: []const u8) ?CtxId {
    if (text.len == 0 or text.len > 6) return null;
    const t = text;
    switch (t[0]) {
        'f' => {
            if (std.mem.eql(u8, t, "from")) return .FROM;
        },
        's' => {
            if (std.mem.eql(u8, t, "static")) return .STATIC;
        },
        'u' => {
            if (std.mem.eql(u8, t, "unique")) return .UNIQUE;
        },
        else => {},
    }
    return null;
}

/// CtxId -> grammar symbol (0 = none)
const ctxToSymbol = blk: {
    var arr: [idCount(CtxId)]u16 = @splat(0);
    arr[@backingInt(CtxId.UNIQUE)] = 143;
    arr[@backingInt(CtxId.FROM)] = 130;
    arr[@backingInt(CtxId.STATIC)] = 131;
    break :blk arr;
};
const ctxFallbackSymbol: u16 = 0;

// A group is declared once: by @keywords or by the lang module (which
// may re-export the generated declarations).
comptime {
    if (@hasDecl(lang, "CtxId") and (@TypeOf(lang.CtxId) != type or lang.CtxId != CtxId) or
        @hasDecl(lang, "ctxAs") and (@TypeOf(lang.ctxAs) != @TypeOf(ctxAs) or lang.ctxAs != ctxAs))
        @compileError("the keyword group ctx is declared by @keywords and by the lang module (CtxId or ctxAs): declare it once");
}

